import React from 'react';

import { SIZE_16 } from '../types/default.js';
import { MeterBarSize } from '../types/meter-bars.js';

export type MeterBarLayoutSizeProps = {
  /**
   * The size that applies to the value, icon, and label.
   * @defaultvalue 'size16'
   */
  size: MeterBarSize;
};

export const MeterBarLayoutSizeContext =
  React.createContext<MeterBarLayoutSizeProps>({
    size: SIZE_16,
  });

export const useMeterBarLayoutSize = () =>
  React.useContext(MeterBarLayoutSizeContext);

useMeterBarLayoutSize['displayName'] = 'useMeterBarLayoutSize';
MeterBarLayoutSizeContext['displayName'] = 'MeterBarLayoutSizeContext';
